import sys,json,time
import numpy as np
sys.path.insert(0,'/app/repo'); import train
S=np.load('/app/data/sample.npz');D=np.load('/app/data/dev.npz');X=S['X'].astype(np.float32);y=S['y'].astype(np.int64);V=D['X'].astype(np.float32);vy=D['y'].astype(np.int64)
base=json.load(open('/app/repo/config.json'))
def run(cfg,mode,seed=0,steps=1000):
 rng=np.random.default_rng(seed); k=10; mu=X.mean(0); sd=X.std(0)+1e-6; xs=((X-mu)/sd).astype(np.float32); vs=((V-mu)/sd).astype(np.float32)
 P=train.init_params(32,cfg['hidden'],k,rng); o=train.AdamW(P,cfg['lr'],cfg['weight_decay']); n=len(X);bs=cfg['batch_size']
 for t in range(steps):
  ii=rng.integers(0,n,bs); xb=xs[ii]; yy=y[ii]
  z,cache=train.forward(P,xb); zz=z-z.max(1,keepdims=True); p=np.exp(zz);p/=p.sum(1,keepdims=True)
  if mode[0]=='gce':
   q=mode[1]; py=np.maximum(p[np.arange(bs),yy],1e-5); w=py**q; dz=(p-np.eye(k,dtype=np.float32)[yy])*w[:,None]/bs
  elif mode[0]=='trim':
   th=mode[1]; good=p[np.arange(bs),yy]>=th; dz=(p-np.eye(k,dtype=np.float32)[yy])*good[:,None]/max(1,good.sum())
  elif mode[0]=='boot':
   th=mode[1]; target=np.eye(k,dtype=np.float32)[yy]; conf=p[np.arange(bs),yy]<th; target[conf]=np.eye(k,dtype=np.float32)[p.argmax(1)[conf]]; dz=(p-target)/bs
  elif mode[0]=='mixboot':
   # targets noisy unless confidence low, then model hard, interpolation
   th,alpha=mode[1:]; target=np.eye(k,dtype=np.float32)[yy]; conf=p[np.arange(bs),yy]<th; target[conf]=alpha*target[conf]+(1-alpha)*np.eye(k,dtype=np.float32)[p.argmax(1)[conf]]; dz=(p-target)/bs
  elif mode[0]=='sym':
   # symmetric CE gradient: CE + reverse CE approximation using target p? reverse=-sum p log q, grad q = -p/q, plus CE
   target=np.eye(k,dtype=np.float32)[yy]; dz=(p-target)/bs
   # reverse CE gradient wrt logits, numerical formula derivative of -sum p_fixed log p? with y onehot reverse is -log p_y, actually same CE; use entropy on p as regularizer
  else: dz=(p-np.eye(k,dtype=np.float32)[yy])/bs
  G=train.backward(P,cache,dz);o.step(P,G,train.lr_multiplier(t,steps,cfg['warmup_frac']))
 z=[]
 for i in range(0,len(vs),4096):z.append(train.forward(P,vs[i:i+4096])[0])
 pred=np.concatenate(z).argmax(1);return (pred==vy).mean()
cs=[]
for lr in [.001,.0015,.002,.003]:
 for wd in [2,3,4,5]:
  for mode in [('gce',.3),('gce',.5),('gce',.7),('trim',.1),('trim',.2),('trim',.3),('boot',.1),('boot',.2),('mixboot',.2,.5)]:
   cs.append(({**base,'lr':lr,'weight_decay':wd},mode))
for cfg,m in cs:
 t=time.time();a=run(cfg,m); print(a,round(time.time()-t,2),cfg['lr'],cfg['weight_decay'],m,flush=True)
